	if parts == 3 {
		switch op {
		case ">=":
			return term{lo: lim(v, true)}
		case ">":
			return term{lo: lim(v, false)}
		case "<":
			return term{hi: lim(v, false)}
		case "<=":
			return term{hi: lim(v, true)}
		}
		return term{lim(v, true), lim(v, true)}
	}
