func Latest(c Constraint, versions []Version) (Version, bool) {
	var best Version
	found := false
	for _, v := range versions {
		if c.Satisfies(v) && (!found || Compare(v, best) > 0) {
			best, found = v, true
		}
	}
	return best, found
}

