		p, ok := number(f[2], 0)
		if !ok {
			return v, 0, ErrVersion
		}
		v.Patch = p
	}
	if hasSuffix {
		kind, num, ok := strings.Cut(suffix, ".")
		n, nok := number(num, 0)
		if !ok || !nok || n < 1 || v.Patch != 0 || (kind != "beta" && kind != "rc") {
			return v, 0, ErrVersion
		}
		v.Pre = n
		v.Channel = Beta
		if kind == "rc" {
			v.Channel = RC
		}
	}
	return v, parts, nil
}

