		v, parts, err := parseOperand(rest)
		if err != nil {
			return term{}, err
		}
		lo := v
		if parts < 3 {
			lo = blockFloor(v, parts)
		}
		return term{lim(lo, true), lim(blockEnd(v, 1), false)}, nil
