	lo, end := blockFloor(v, parts), blockEnd(v, parts)
	switch op {
	case ">=":
		return term{lo: lim(lo, true)}
	case ">":
		return term{lo: lim(end, true)}
	case "<":
		return term{hi: lim(lo, false)}
	case "<=":
